INSERT = sa.text(
    "INSERT INTO journals (direction_id, title, base, url) "
    "SELECT d.id, CAST(:title AS TEXT), CAST(:base AS VARCHAR), CAST(:url AS VARCHAR) "
    "FROM directions d WHERE d.sort_order = :sort_order "
    "AND NOT EXISTS (SELECT 1 FROM journals j WHERE j.title = CAST(:title AS TEXT) AND j.url = CAST(:url AS VARCHAR))"
)


def upgrade() -> None:
    # Admin oldin qo'shgan jurnallar (nomi va havolasi bir xil) takrorlanmaydi
    op.get_bind().execute(INSERT, [
        {'sort_order': sort_order, 'title': title, 'base': base, 'url': url}
        for sort_order, title, base, url in JOURNALS
    ])


def downgrade() -> None:
    op.get_bind().execute(
        sa.text("DELETE FROM journals WHERE title = :title AND url = :url"),
        [{'title': title, 'url': url} for _, title, _, url in JOURNALS],
    )
